import os, json, hashlib
from pathlib import Path
root=Path.cwd()
entries={}
for base, dirs, files in os.walk(root, followlinks=False):
    for name in dirs+files:
        p=Path(base)/name
        rel=p.relative_to(root).as_posix()
        s=p.lstat()
        if p.is_symlink():
            entries[rel]=['symlink',s.st_mode,os.readlink(p)]
        elif p.is_file():
            entries[rel]=['file',s.st_mode,hashlib.sha256(p.read_bytes()).hexdigest()]
        else:
            entries[rel]=['directory',s.st_mode]
assessment=json.loads((root/'assessment.json').read_text())
assert set(assessment)=={'stage','known_blockers','verification_scope','execution_authorized','next_action'}
assert assessment['execution_authorized'] is False
print(json.dumps({'entries':entries,'assessment':assessment},sort_keys=True))
